// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    // Fuzzed parameters: an initial owner private key (uint256 key) to derive an address that becomes the current owner,
    // and a fuzzed address newOwner that we will transfer ownership to.
    function testFuzz_property(uint256 ownerKey, address newOwner) public {
        ownerKey = bound(ownerKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // Keep the domain wide but avoid the zero private key which maps to address(0) rarely useful in forge vm.addr
        vm.assume(ownerKey != 0);

        address initialOwner = vm.addr(ownerKey);

        // Make sure the initialOwner has some ETH to send txs
        vm.deal(initialOwner, 1 ether);

        // Set the contract's owner to initialOwner by using transferOwnership from the deployer only if deployer is current owner.
        // But in reference C the owner is default 0x0; we need to make initialOwner the owner to be able to call transferOwnership.
        // Since the PUBLIC surface only allows transferOwnership guarded by onlyOwner, we can set owner by directly constructing
        // and then using vm.prank on address 0 (the initial owner is address(0) in deployed c) to call transferOwnership.

        // At deployment, c.owner() == address(0). So to make initialOwner be the current owner, have address(0) call transferOwnership(initialOwner).
        // vm.prank can set msg.sender to address(0) for the next call.
        vm.prank(address(0));
        c.transferOwnership(initialOwner);

        // Sanity: now initialOwner must be the owner on the reference contract for all admissible inputs
        assertTrue(c.owner() == initialOwner);

        // Now from initialOwner, call transferOwnership(newOwner). This is the decisive action.
        vm.prank(initialOwner);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference always allows the current owner to call transferOwnership (no revert branch) and sets owner = newOwner.
        // Some mutants remove the assignment and thus after a successful call owner() != newOwner. We assert the universal property:
        // for any admissible inputs (ownerKey != 0), after the current owner calls transferOwnership(newOwner), c.owner() equals newOwner.
        // This single assert is true for the reference for all admissible inputs and false for the mutant that deleted the assignment
        // for at least some fuzzed newOwner values.
        assertTrue(ok && c.owner() == newOwner);
    }
}
